export async function quoteStage(config,{root=ROOT,now=Date.now(),rpc,journal}={}) {
 const source=await captureSource({root,final:true});validatePrincipals(config.principals);const role=STAGES[config.stage];assert.ok(role,"Unsupported stage");const chainId=role==="genlayerOperator"?61999:196;rpc??=new DeploymentRpc({chainId});assert.equal(rpc.chainId,chainId);const releaseId=releaseIdentity(source,config.principals);journal??=new DeploymentJournal(resolve(root,".local/mainnet-deployment",releaseId,"journal.json"),releaseId);await verifySources({root});const build=await collectCompiled({root});const block=await rpc.pin(now);const protocol=chainId===196?await observeProtocol(rpc):{...REVIEW,block,trust:"Studionet simulator; a single endpoint, not independent EVM deployment proof"};const op=await buildOperation(config,{source,build,journal,rpc,block});
 const nonce=quantity(await rpc.request("eth_getTransactionCount",[op.sender,"pending"]));const call=txRpc(op);const returned=await rpc.request("eth_call",[call,block.number]);hex(returned,"simulation return");const gas=quantity(await rpc.request("eth_estimateGas",[call,block.number]));assert.ok(gas>0n,"Zero estimated gas");const recommendations=await Promise.all(rpc.urls.map(url=>rpc.single(url,"eth_gasPrice",[]).then(v=>quantity(v).toString())));const gasPriceWei=recommendations.reduce((a,b)=>uint(a)>uint(b)?a:b);const gasLimit=(gas*125n/100n+50000n).toString();const tx={sender:op.sender,to:op.to,data:op.data,valueWei:op.valueWei,nonce:nonce.toString(),gasLimit,gasPriceWei,type:"legacy",chainId};const maximumCostWei=(uint(tx.valueWei)+uint(gasLimit)*uint(gasPriceWei)).toString();assert.ok(quantity(await rpc.request("eth_getBalance",[op.sender,block.number]))>=uint(maximumCostWei),"Insufficient balance for exact stage");const end=await rpc.request("eth_getBlockByNumber",[block.number,false]);assert.equal(end.hash,block.hash,"Quote block reorged");const currentSource=await captureSource({root,final:true});assert.equal(currentSource.treeSha256,source.treeSha256,"Source changed during quote");return seal({version:1,kind:"intentguard-exact-deployment-stage",releaseId,sourceCommit:source.commit,sourceTreeSha256:source.treeSha256,principals:config.principals,pinsSha256:digest(PINS),stage:config.stage,stageKey:op.stageKey,role,chainId,createdAt:now,expiresAt:now+300000,block,protocol,operation:op.operation,transaction:tx,simulation:{gas:gas.toString(),gasPriceRecommendations:recommendations,returnSha256:hash(Buffer.from(returned.slice(2),"hex")),returnBytes:(returned.length-2)/2,transactionSha256:digest(call),blockHash:block.hash},maximumCostWei,tokenCost:op.tokenCost,disclosures:["This quote authorizes no signing or broadcasting; explicit user approval of this exact hash and stage cap is required.","The maximum native cost bounds value plus the exact signed gas limit and gas price; future dependent stages have separate unresolved fees.","The fixed gas-price ceiling is the larger independently measured provider recommendation; the original measurements are recorded even when they disagree.","Mainnet payments use X Layer196; GenLayer Studionet61999 review is testnet and simulator infrastructure, with no independent finality endpoint.","Factory/admin runtime pins are source observations and do not constitute a third-party security audit."]},"quoteHash");
}

export async function recheckStage(q,{config,source,journal,rpc}) {
 validateQuote(q,{source,principals:config.principals});const currentSource=await captureSource({final:true});validateSource(currentSource,{current:source,final:true});await verifySources();const b=await rpc.pin();const old=await rpc.request("eth_getBlockByNumber",[q.block.number,false]);assert.equal(old.hash,q.block.hash,"Quoted block reorged");const build=await collectCompiled();const operation=await buildOperation(config,{source,build,journal,rpc,block:b});assert.equal(operation.stageKey,q.stageKey);assert.equal(operation.sender,q.transaction.sender);assert.equal(operation.to,q.transaction.to);assert.equal(operation.data,q.transaction.data,"Dependent calldata changed");assert.equal(operation.valueWei,q.transaction.valueWei,"Fee changed");assert.deepEqual(operation.operation,q.operation,"Dependency identity changed");assert.deepEqual(operation.tokenCost,q.tokenCost);
 if(q.chainId===196){const p=await observeProtocol(rpc);const {block:ignored,...oldP}=q.protocol,{block:ignored2,...newP}=p;assert.deepEqual(newP,oldP,"Official protocol admin/implementation/fee configuration changed");}
 const simulated=await rpc.request("eth_call",[txRpc(q.transaction),b.number]);hex(simulated);const gas=quantity(await rpc.request("eth_estimateGas",[txRpc(q.transaction),b.number]));assert.ok(gas<=uint(q.transaction.gasLimit),"Current gas estimate exceeds approved limit");const recommendations=await Promise.all(rpc.urls.map(url=>rpc.single(url,"eth_gasPrice",[]).then(quantity)));assert.ok(recommendations.every(v=>v<=uint(q.transaction.gasPriceWei)),"Gas price exceeds approved ceiling");
}

export async function verifyStageOutcome(rpc,q,receipt,at) {
 const op=q.operation;
 if(q.stage==="createCPU"){const e=event(receipt,PINS.contracts.factory,"CPUCreated");const processor=nonzero(e.circuits,"processor"),transistors=nonzero(e.transistors,"transistors");assert.equal(e.creator,q.transaction.sender);assert.equal(e.name,"IntentGuard");assert.equal(e.supply,"10000");assert.equal(e.mintPrice,"0");assert.equal(await rpc.call(PINS.contracts.factory,"isCPU",[processor],at),true);const cpuIndex=await receiptCpuIndex(rpc,processor,op.cpuIndex,at);assert.equal(slotAddress(await rpc.request("eth_getStorageAt",[processor,BEACON_SLOT,at])),PINS.contracts.beacon);assert.equal(address(await rpc.call(processor,"transistors",[],at)),transistors);return {processor,transistors,cpuIndex,processorRuntimeSha256:hash(Buffer.from((await code(rpc,processor,at)).slice(2),"hex")),transistorRuntimeSha256:hash(Buffer.from((await code(rpc,transistors,at)).slice(2),"hex")),beacon:PINS.contracts.beacon,implementation:PINS.contracts.circuitImplementation};}
 if(q.stage==="deployUSDCFactory"||q.stage==="deployUSDT0Factory"){const deployed=nonzero(receipt.contractAddress?.toLowerCase(),"factory address");assert.equal(deployed,getContractAddress({from:q.transaction.sender,nonce:uint(q.transaction.nonce)}).toLowerCase());const a=await artifact(op.contract);assert.equal(hash(Buffer.from(a.bytecode.object.slice(2),"hex")),op.creationSha256);const runtime=await code(rpc,deployed,at);compareRuntime(runtime,a.deployedBytecode.object,a.deployedBytecode.immutableReferences??{});
  if(q.stage==="deployUSDCFactory"){assert.equal(await rpc.call(deployed,"sourceChainId",[],at,READ_ABI),196n);const prefix=address(await rpc.call(deployed,"creationPrefix",[],at,READ_ABI)),suffix=address(await rpc.call(deployed,"creationSuffix",[],at,READ_ABI));const p=await code(rpc,prefix,at),s=await code(rpc,suffix,at);assert.equal(p.slice(0,4),"0x00");assert.equal(s.slice(0,4),"0x00");assert.equal(keccak256(p),await rpc.call(deployed,"creationPrefixCodeHash",[],at,READ_ABI));assert.equal(keccak256(s),await rpc.call(deployed,"creationSuffixCodeHash",[],at,READ_ABI));assert.equal(BigInt((p.length-4)/2),await rpc.call(deployed,"creationPrefixLength",[],at,READ_ABI));assert.equal(BigInt((s.length-4)/2),await rpc.call(deployed,"creationSuffixLength",[],at,READ_ABI));assert.equal("0x"+p.slice(4)+s.slice(4),(await artifact("CctpSpendingCardV4")).bytecode.object,"Factory stored card image mismatch");}
  else {assert.equal(await rpc.call(deployed,"SOURCE_CHAIN_ID",[],at,READ_ABI),196n);assert.equal(address(await rpc.call(deployed,"SOURCE_USDT0",[],at,READ_ABI)),sourceToken("mainnet","USDT0"));assert.equal(await rpc.call(deployed,"tokenCodeHash",[],at,READ_ABI),keccak256(await code(rpc,sourceToken("mainnet","USDT0"),at)));}
  return {address:deployed,contract:op.contract,runtimeSha256:hash(Buffer.from(runtime.slice(2),"hex")),sourceChainId:196};}
 if(q.stage==="mintTransistors"){assert.ok(await rpc.call(op.transistors,"balanceOf",[q.transaction.sender,0n],at)>=uint(op.heldBefore)+uint(op.amount));return {processor:op.processor,transistors:op.transistors,amount:op.amount};}
 if(q.stage==="tapeout"){const e=event(receipt,op.processor,"TapedOut");assert.equal(e.author,q.transaction.sender);assert.equal(e.gateCount,1766);assert.equal(e.nState,0);const circuitId=e.circuitId;const netlist=await rpc.call(op.processor,"netlist",[uint(circuitId)],at);assert.equal(hash(Buffer.from(netlist.slice(2),"hex")),op.netlistSha256);assert.deepEqual(await rpc.call(op.processor,"circuitInfo",[uint(circuitId)],at),[451,8,0,1766]);assert.equal(address(await rpc.call(op.processor,"ownerOf",[uint(circuitId)],at)),q.transaction.sender);return {processor:op.processor,cpuIndex:op.cpuIndex,circuitId,netlistSha256:op.netlistSha256,gateCount:1766,inputBits:451,outputBits:8,independentLiveVectorsVerified:false};}
 if(q.stage==="transferCircuit"){assert.equal(address(await rpc.call(op.processor,"ownerOf",[uint(op.circuitId)],at)),op.newOwner);return {processor:op.processor,circuitId:op.circuitId,owner:op.newOwner};}
 if(q.stage==="openContainer"){assert.equal(await rpc.call(PINS.contracts.opener,"isOpened",[op.processor,uint(op.circuitId)],at),true);assert.equal(address(await rpc.call(PINS.contracts.opener,"accountOf",[op.processor,uint(op.circuitId)],at)),op.container);const token=await rpc.call(op.container,"token",[],at);assert.equal(token[0],196n,"Container token chain mismatch");assert.equal(address(token[1]),op.processor,"Container token processor mismatch");assert.equal(token[2],uint(op.circuitId),"Container token ID mismatch");assert.equal(await rpc.call(PINS.contracts.registry,"isOpenedContainer",[op.container],at),true);return {container:op.container,processor:op.processor,circuitId:op.circuitId};}
 if(q.stage==="uploadFrontend"){const progress=await inspectFile(rpc,op.container,op.file,at);assert.equal(progress.verifiedChunks,op.chunkIndex+1,"Unexpected upload progress");return {path:op.file.path,sha256:op.file.sha256,verifiedChunks:progress.verifiedChunks,bundleSha256:op.bundleSha256};}
 if(q.stage==="setFallback"){assert.equal(await rpc.call(PINS.contracts.registry,"fallbackPath",[op.container],at),op.fallback);return {container:op.container,fallback:op.fallback,bundleSha256:op.bundleSha256};}
 if(q.stage==="activateFrontend"){const paid=await rpc.call(PINS.contracts.binding,"containerPaidUntil",[op.container],at);assert.ok(paid>BigInt(Math.floor(q.createdAt/1000)));return {container:op.container,name:op.name,paidUntil:paid.toString(),bundleSha256:op.bundleSha256,liveBrowserVerified:false};}
 if(q.stage==="createCanaryVault"){const e=event(receipt,op.factory,"CardCreated");assert.equal(e.owner,q.transaction.sender);assert.equal(e.policyHash,op.cardConfig.policyHash);const a=nonzero(e.card,"vault");assert.equal(await rpc.call(op.factory,"isCard",[a],at,READ_ABI),true);const art=await artifact(op.asset==="USDC"?"CctpSpendingCardV4":"AgentSpendingCard");compareRuntime(await code(rpc,a,at),art.deployedBytecode.object,art.deployedBytecode.immutableReferences??{});for(const key of Object.keys(op.cardConfig).filter(k=>k!=="allowedRecipients")){const actual=await rpc.call(a,key,[],at,art.abi);assert.equal(typeof actual==="bigint"?actual.toString():actual.toLowerCase(),op.cardConfig[key]);}assert.deepEqual((await rpc.call(a,"allowedRecipients",[],at,art.abi)).map(address),op.cardConfig.allowedRecipients);if(op.asset==="USDC"){assert.equal(await rpc.call(a,"sourceChainId",[],at,art.abi),196n);const domains=op.destinations.map(id=>profileRoutes("mainnet")[id].domain).sort((a,b)=>a-b);assert.deepEqual([...(await rpc.call(a,"allowedDomains",[],at,art.abi))].sort((a,b)=>a-b),domains);for(const id of op.destinations){const d=profileRoutes("mainnet")[id].domain;assert.equal(await rpc.call(a,"destinationChainId",[d],at,art.abi),BigInt(id));assert.equal(address(await rpc.call(a,"destinationToken",[d],at,art.abi)),profileRoutes("mainnet")[id].token);}}return {address:a,asset:op.asset,token:op.cardConfig.token,policyHash:op.cardConfig.policyHash,destinations:op.destinations,spendingWindowStarts:op.cardConfig.validFrom,liveReviewVerified:false};}
 if(q.stage==="pauseCanary"){assert.equal(await rpc.call(op.vault,"enabled",[],at,parseAbi(["function enabled() view returns(bool)"])),false);return {vault:op.vault,enabled:false};}
 if(q.stage==="fundCanary"){const e=event(receipt,op.token,"Transfer");assert.equal(e.from,q.transaction.sender);assert.equal(e.to,op.vault);assert.equal(e.value,op.amountUnits);assert.ok(await rpc.call(op.token,"balanceOf",[op.vault],at,parseAbi(["function balanceOf(address) view returns(uint256)"]))>=uint(op.balanceBefore)+uint(op.amountUnits));return {vault:op.vault,token:op.token,amountUnits:op.amountUnits};}
 if(q.stage==="deployInterpreter"||q.stage==="deployReviewer")return verifyGenLayerDeployment(q,receipt);
 throw Error("Unsupported receipt stage");
}

export async function verifyGenLayerDeployment(q,receipt,{client}={}) {
 const {createClient,decodeInputData}=await import("genlayer-js"),{studionet}=await import("genlayer-js/chains"),{TransactionHashVariant,transactionsStatusNumberToName,transactionResultNumberToName,CalldataAddress}=await import("genlayer-js/types");client??=createClient({chain:studionet,endpoint:REVIEW.rpcUrl});let protocolHash=receipt.transactionHash;
 for(const log of receipt.logs??[]){if(log.address?.toLowerCase()!==REVIEW.consensus)continue;try{const e=decodeEventLog({abi:studionet.consensusMainContract.abi,data:log.data,topics:log.topics});if(["NewTransaction","CreatedTransaction"].includes(e.eventName)&&e.args.txId)protocolHash=e.args.txId;}catch{}}
 const tx=await client.getTransaction({hash:protocolHash});const status=tx.statusName??tx.status_name??transactionsStatusNumberToName[String(tx.status)]??tx.status;assert.ok(!["CANCELED","UNDETERMINED","VALIDATORS_TIMEOUT","LEADER_TIMEOUT"].includes(String(status)),"GenLayer deployment consensus failed");if(status!=="FINALIZED")return {status:"PENDING_FINALITY",protocolHash};
 let decoded=tx.txDataDecoded;if(typeof tx.tx_data==="string")decoded=decodeInputData(tx.tx_data.startsWith("0x")?tx.tx_data:"0x"+tx.tx_data,tx.recipient??tx.to_address);assert.ok(decoded&&decoded.type==="deploy"&&decoded.leaderOnly===false,"Finalized source-bound validator deployment is required");assert.equal(decoded.code,q.operation.sourceCode,"Deployed GenLayer source mismatch");const normalize=v=>{if(v instanceof CalldataAddress)return toHex(v.bytes).toLowerCase();if(typeof v==="bigint"){assert.ok(v<=BigInt(Number.MAX_SAFE_INTEGER));return Number(v);}if(v instanceof Map)return Object.fromEntries([...v].map(([k,x])=>[k,normalize(x)]));if(Array.isArray(v))return v.map(normalize);if(v&&typeof v==="object")return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,normalize(x)]));return v;};assert.deepEqual(normalize(decoded.constructorArgs)?.args,q.operation.constructorArgs,"GenLayer constructor binding mismatch");assert.equal((tx.sender??tx.from_address)?.toLowerCase(),q.transaction.sender,"GenLayer deployer mismatch");const leaders=tx.consensus_data?.leader_receipt;const receipts=Array.isArray(leaders)?leaders:leaders?[leaders]:[];const latest=(receipts.some(r=>r.mode)?receipts.filter(r=>r.mode==="leader"):receipts).at(-1);if(latest){assert.equal(latest.execution_result,"SUCCESS");assert.ok(!latest.result?.status||latest.result.status==="return");}else assert.equal(tx.txExecutionResultName,"FINISHED_WITH_RETURN","No successful VM result");const result=tx.resultName??tx.result_name??transactionResultNumberToName[String(tx.result)];assert.ok(["AGREE","MAJORITY_AGREE","SUCCESS"].includes(String(result)),"GenLayer deployment execution not approved");const contract=nonzero((decoded.contractAddress??tx.recipient??tx.to_address)?.toLowerCase(),"GenLayer contract");const read=fn=>client.readContract({address:getAddress(contract),functionName:fn,args:[],jsonSafeReturn:true,transactionHashVariant:TransactionHashVariant.LATEST_FINAL});assert.equal(String(await read("get_operator")).toLowerCase(),q.transaction.sender);if(q.stage==="deployReviewer"){assert.equal(Number(await read("get_version")),4);assert.equal(Number(await read("get_chain_id")),196);assert.equal(String(await read("get_token")).toLowerCase(),q.operation.constructorArgs[4]);assert.equal(String(await read("get_policy_hash")),q.operation.constructorArgs[2]);assert.equal(String(await read("get_settlement_profile")),q.operation.constructorArgs[6]);assert.equal(String(await read("get_settlement_hash")),"0x"+hash(q.operation.constructorArgs[5]));}return {address:contract,protocolHash,sourceSha256:q.operation.sourceSha256,constructorSha256:digest(q.operation.constructorArgs),review:REVIEW,finalized:true,semanticAuditPassed:false};
}

export async function main(args=process.argv.slice(2)) {
 const command=args[0];assert.ok(["quote","execute","reconcile"].includes(command),"Use quote, execute or reconcile with one JSON config file");assert.ok(args[1]);assert.ok(args.length===2||(command==="execute"&&args.length===3&&args[2]==="--broadcast"),"Unsupported arguments");const config=await rawJson(resolve(args[1]));const allowed=["stage","principals","quotePath","approvalPath","dependencyEvidence","frontendDirectory","apiOrigins","path","months","browserAcceptance","asset","cardConfig","destinations","canaryId","amountUnits","reviewer","stageKey"];for(const k of Object.keys(config))assert.ok(allowed.includes(k),"Unsupported configuration field: "+k);const source=await captureSource({final:true}),releaseId=releaseIdentity(source,config.principals);const chainId=STAGES[config.stage]==="genlayerOperator"?61999:196;assert.ok(Object.hasOwn(STAGES,config.stage));const rpc=new DeploymentRpc({chainId}),journal=new DeploymentJournal(resolve(ROOT,".local/mainnet-deployment",releaseId,"journal.json"),releaseId);
 if(command==="quote"){const q=await quoteStage(config,{rpc,journal});validateQuote(q,{source,principals:config.principals});console.log(JSON.stringify(q,null,2));return;}
 if(command==="reconcile"){console.log(JSON.stringify(await reconcileStage({journal,rpc,stageKey:config.stageKey??config.stage}),null,2));return;}
 assert.equal(args[2],"--broadcast","Explicit --broadcast required");assert.ok(config.quotePath&&config.approvalPath,"Exact quote and explicit user approval files required");const quote=await rawJson(resolve(config.quotePath)),approval=await rawJson(resolve(config.approvalPath));validateQuote(quote,{source,principals:config.principals});validateApproval(approval,quote);assert.equal(quote.stage,config.stage);const variable={deployer:"INTENTGUARD_MAINNET_DEPLOYER_PRIVATE_KEY",owner:"INTENTGUARD_MAINNET_OWNER_PRIVATE_KEY",genlayerOperator:"INTENTGUARD_MAINNET_GENLAYER_OPERATOR_PRIVATE_KEY"}[quote.role];assert.ok(variable&&process.env[variable],"Dedicated role signer environment variable is required");const signer=privateKeyToAccount(process.env[variable]);const result=await executeStage({quote,approval,source,principals:config.principals,journal,rpc,signer,broadcast:true,recheck:q=>recheckStage(q,{config,source,journal,rpc})});console.log(JSON.stringify(result,null,2));
}
if(process.argv[1]&&pathToFileURL(resolve(process.argv[1])).href===import.meta.url){try{await main();}catch(e){console.error("Mainnet stage refused: "+String(e.message).slice(0,800));process.exitCode=1;}}
